import{c as t,Z as l,Q as r,j as s,g as e,n,o,m as u}from"./chunks/framework.BPKcPtvA.js";const P=JSON.parse('{"title":"User Guide","description":"","frontmatter":{"title":"User Guide","outline":"deep"},"headers":[],"relativePath":"guide/user-guide.md","filePath":"guide/user-guide.md"}'),d={name:"guide/user-guide.md"},k={id:"user-guide",tabindex:"-1"};function h(m,a,g,b,c,p){const i=l("Badge");return r(),s("div",null,[e("h1",k,[a[0]||(a[0]=n("User Guide ",-1)),o(i,{type:"tip",text:"^0.3"}),a[1]||(a[1]=n()),a[2]||(a[2]=e("a",{class:"header-anchor",href:"#user-guide","aria-label":'Permalink to "User Guide <Badge type="tip" text="^0.3" />"'},"​",-1))]),a[3]||(a[3]=u('<h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p>Panduan ini membantu pengguna memahami cara menggunakan dashboard TMS untuk memantau transaksi dan performa operasional.</p><h2 id="akses-dashboard" tabindex="-1">Akses Dashboard <a class="header-anchor" href="#akses-dashboard" aria-label="Permalink to &quot;Akses Dashboard&quot;">​</a></h2><ul><li>Login ke aplikasi TMS menggunakan akun yang terdaftar.</li><li>Setelah login, buka halaman Dashboard melalui menu utama.</li></ul><h2 id="menggunakan-filter-periode-bulan-tahun" tabindex="-1">Menggunakan Filter Periode (bulan/tahun) <a class="header-anchor" href="#menggunakan-filter-periode-bulan-tahun" aria-label="Permalink to &quot;Menggunakan Filter Periode (bulan/tahun)&quot;">​</a></h2><ul><li>Gunakan dropdown bulan dan tahun pada ringkasan Sales Cost.</li><li>Perubahan filter akan memperbarui nilai Sales, Total Cost, dan Gross Profit.</li></ul><h2 id="membaca-ringkasan-sales-cost" tabindex="-1">Membaca Ringkasan Sales Cost <a class="header-anchor" href="#membaca-ringkasan-sales-cost" aria-label="Permalink to &quot;Membaca Ringkasan Sales Cost&quot;">​</a></h2><ul><li>Sales menunjukkan total pendapatan periode terpilih.</li><li>Total Cost menunjukkan total biaya operasional.</li><li>Gross Profit adalah selisih antara Sales dan Total Cost.</li></ul><h2 id="monitoring-subcontractor" tabindex="-1">Monitoring Subcontractor <a class="header-anchor" href="#monitoring-subcontractor" aria-label="Permalink to &quot;Monitoring Subcontractor&quot;">​</a></h2><ul><li>Pantau transaksi subcontractor untuk melihat kontribusi biaya eksternal.</li><li>Bandingkan tren subcontractor dengan transaksi internal.</li></ul><h2 id="analisis-transaksi-bulanan" tabindex="-1">Analisis Transaksi Bulanan <a class="header-anchor" href="#analisis-transaksi-bulanan" aria-label="Permalink to &quot;Analisis Transaksi Bulanan&quot;">​</a></h2><ul><li>Lihat grafik Monthly Sales Transaction untuk tren per bulan.</li><li>Gunakan filter tahun untuk membandingkan data historis.</li></ul><h2 id="detail-sales-cost-monthly" tabindex="-1">Detail Sales Cost (Monthly) <a class="header-anchor" href="#detail-sales-cost-monthly" aria-label="Permalink to &quot;Detail Sales Cost (Monthly)&quot;">​</a></h2><ul><li>Perhatikan nilai Sales, Total Cost, dan Gross Profit.</li><li>Gunakan indikator perubahan untuk membaca perbandingan dengan periode sebelumnya.</li></ul><h2 id="melihat-demografi-pelanggan" tabindex="-1">Melihat Demografi Pelanggan <a class="header-anchor" href="#melihat-demografi-pelanggan" aria-label="Permalink to &quot;Melihat Demografi Pelanggan&quot;">​</a></h2><ul><li>Gunakan peta untuk memahami sebaran pelanggan.</li><li>Amati persentase per negara sebagai acuan fokus pasar.</li></ul><h2 id="mengelola-event-kalender" tabindex="-1">Mengelola Event Kalender <a class="header-anchor" href="#mengelola-event-kalender" aria-label="Permalink to &quot;Mengelola Event Kalender&quot;">​</a></h2><ul><li>Periksa Calendar Event List untuk aktivitas terbaru.</li><li>Gunakan filter tanggal untuk fokus pada rentang tertentu.</li><li>Klik See All untuk melihat kalender lengkap.</li></ul><h2 id="hak-akses-user" tabindex="-1">Hak Akses User <a class="header-anchor" href="#hak-akses-user" aria-label="Permalink to &quot;Hak Akses User&quot;">​</a></h2><ul><li>User memiliki akses baca terhadap ringkasan dan statistik.</li><li>Perubahan data hanya dapat dilakukan sesuai izin yang diberikan admin.</li></ul><h2 id="troubleshooting-user" tabindex="-1">Troubleshooting User <a class="header-anchor" href="#troubleshooting-user" aria-label="Permalink to &quot;Troubleshooting User&quot;">​</a></h2><ul><li>Data tidak tampil: pastikan koneksi internet stabil dan refresh halaman.</li><li>Grafik kosong: periksa filter tahun/bulan, mungkin tidak ada data.</li><li>Event tidak muncul: pastikan filter tanggal sesuai.</li><li>Tidak bisa akses dashboard: periksa status login dan izin akun.</li><li>Perubahan tidak tersimpan: cek apakah akun memiliki hak akses edit.</li></ul>',22))])}const q=t(d,[["render",h]]);export{P as __pageData,q as default};
